use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use mongodb::{Client, Collection, bson::doc};
use std::sync::Arc;
use tokio::sync::RwLock;
use std::collections::HashMap;

#[derive(Clone, Debug, Serialize, Deserialize)]
struct User {
    username: String,
    role: String,
    permission_level: u8,
    tenant_id: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct Document {
    id: String,
    title: String,
    content: String,
    tenant_id: String,
    required_level: u8,
}

#[derive(Deserialize)]
struct CreateDocRequest {
    title: String,
    content: String,
    required_level: u8,
}

#[derive(Deserialize)]
struct ShareRequest {
    target_user: String,
    document_id: String,
    additional_permissions: u8,
}

struct AppState {
    db: Client,
    sessions: RwLock<HashMap<String, User>>,
}

impl AppState {
    fn get_documents_collection(&self) -> Collection<mongodb::bson::Document> {
        self.db.database("docstore").collection("documents")
    }

    fn get_shares_collection(&self) -> Collection<mongodb::bson::Document> {
        self.db.database("docstore").collection("shares")
    }

    async fn get_user_from_token(&self, token: &str) -> Option<User> {
        let sessions = self.sessions.read().await;
        sessions.get(token).cloned()
    }

    /// Computes effective permission level for a user accessing a shared document.
    /// The base permission_level of the user is combined with any additional_permissions
    /// granted through the sharing mechanism.
    /// Returns the effective level that should be compared against the document's required_level.
    fn compute_effective_level(&self, user_level: u8, additional: u8) -> u8 {
        // Combine base permission with additional grants, capping at maximum
        user_level.saturating_add(additional)
    }

    /// Check if the effective permission level meets the document requirement.
    /// Documents with required_level 0 are public.
    /// Higher required_level means more restricted.
    fn check_permission_level(&self, effective_level: u8, required_level: u8) -> bool {
        // A user can access a document if their effective level >= required level
        effective_level >= required_level
    }
}

async fn extract_user(req: &HttpRequest, state: &AppState) -> Option<User> {
    let token = req.headers().get("Authorization")?
        .to_str().ok()?
        .strip_prefix("Bearer ")?;
    state.get_user_from_token(token).await
}

async fn get_document(
    req: HttpRequest,
    path: web::Path<String>,
    state: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let user = match extract_user(&req, &state).await {
        Some(u) => u,
        None => return HttpResponse::Unauthorized().finish(),
    };

    let doc_id = path.into_inner();
    let collection = state.get_documents_collection();

    // Safe: scalar binding via doc! macro, tenant isolation enforced
    let filter = doc! {
        "id": &doc_id,
        "tenant_id": &user.tenant_id,
    };

    let document = match collection.find_one(filter).await {
        Ok(Some(d)) => d,
        Ok(None) => return HttpResponse::NotFound().finish(),
        Err(_) => return HttpResponse::InternalServerError().finish(),
    };

    let required_level = document.get_i32("required_level").unwrap_or(0) as u8;

    // Check if user has direct permission
    if state.check_permission_level(user.permission_level, required_level) {
        return HttpResponse::Ok().json(&document);
    }

    // Check if user has been granted additional permissions via sharing
    let shares_collection = state.get_shares_collection();
    let share_filter = doc! {
        "target_user": &user.username,
        "document_id": &doc_id,
    };

    if let Ok(Some(share)) = shares_collection.find_one(share_filter).await {
        let additional = share.get_i32("additional_permissions").unwrap_or(0) as u8;
        let effective = state.compute_effective_level(user.permission_level, additional);

        if state.check_permission_level(effective, required_level) {
            return HttpResponse::Ok().json(&document);
        }
    }

    HttpResponse::Forbidden().json("Insufficient permission level")
}

async fn share_document(
    req: HttpRequest,
    body: web::Json<ShareRequest>,
    state: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let user = match extract_user(&req, &state).await {
        Some(u) => u,
        None => return HttpResponse::Unauthorized().finish(),
    };

    // Only admins can share documents
    if user.role != "admin" {
        return HttpResponse::Forbidden().finish();
    }

    // Validate the document exists and belongs to the same tenant
    let collection = state.get_documents_collection();
    let doc_filter = doc! {
        "id": &body.document_id,
        "tenant_id": &user.tenant_id,
    };

    if let Ok(None) = collection.find_one(doc_filter).await {
        return HttpResponse::NotFound().finish();
    }

    // Cap additional_permissions to prevent overflow-based bypass
    let max_additional: u8 = 255u8.saturating_sub(50); // reasonable cap
    let capped_additional = body.additional_permissions.min(max_additional);

    // Store the share grant
    let shares_collection = state.get_shares_collection();
    let share_doc = doc! {
        "target_user": &body.target_user,
        "document_id": &body.document_id,
        "additional_permissions": capped_additional as i32,
        "granted_by": &user.username,
    };

    match shares_collection.insert_one(share_doc).await {
        Ok(_) => HttpResponse::Ok().json("Share created"),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

async fn create_document(
    req: HttpRequest,
    body: web::Json<CreateDocRequest>,
    state: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let user = match extract_user(&req, &state).await {
        Some(u) => u,
        None => return HttpResponse::Unauthorized().finish(),
    };

    if user.role != "admin" {
        return HttpResponse::Forbidden().finish();
    }

    let collection = state.get_documents_collection();
    let doc_id = uuid::Uuid::new_v4().to_string();

    let new_doc = doc! {
        "id": &doc_id,
        "title": &body.title,
        "content": &body.content,
        "tenant_id": &user.tenant_id,
        "required_level": body.required_level as i32,
    };

    match collection.insert_one(new_doc).await {
        Ok(_) => HttpResponse::Created().json(doc_id),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let client = Client::with_uri_str("mongodb://localhost:27017").await
        .expect("Failed to connect to MongoDB");

    let state = Arc::new(AppState {
        db: client,
        sessions: RwLock::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/documents/{id}", web::get().to(get_document))
            .route("/documents", web::post().to(create_document))
            .route("/share", web::post().to(share_document))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
